final class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word0: String): Option[String] = {
    val stripped =
      if (!stripPunctuation) word0
      else word0.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse

    val cased = if (lowercase) stripped.toLowerCase else stripped

